// Runs ONCE for the entire batch (not once per item).
// Counts how many users were just processed and computes the new checkpoint.
// Failed Discord calls still count — checkpoint advances past them.
const processed = $input.all().length;
const config    = $('📋 Read Config').first().json;
return [{
  json: {
    guild_id:   config.guild_id,
    checkpoint: parseInt(config.checkpoint) + processed
  }
}];
